return {rwnpc01={id="rwnpc01",title="BLU时间缺失大师NOR",dsc="看模样像是个幼童，但因为实在太小只，所以判断不清性别。明明看上去是个小孩，说话的口气却是个十足的大人。小小的身子在桌子前忙得团团转，根本停不下来。",sex="野兽",age=3,looks=25,showequip={},withCorpse=0},rwnpc02={id="rwnpc02",dsc="他正是红松阁的表面首脑，实为高级打杂， 每天身份于压榨别人和被压榨之间来回切换，练就出一身厚脸皮神功。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc03={id="rwnpc03",dsc="此人曾是戍卫边疆的武官，身长八尺有余，豹头环眼，壮如蛮牛，皮肤黝黑，下颚上留有钢针般遒劲的浓密胡须。",sex="男",age=49,looks=18,showequip={},withCorpse=0},rwnpc04={id="rwnpc04",dsc="此人头戴斗笠看不清面容，但其气息内敛，应当是个高手。",sex="野兽",age=30,looks=20,showequip={},withCorpse=0},rwnpc05={id="rwnpc05",title="BLU工具人NOR",dsc="她穿着宽松大袍，带着一个白色的面具，看不出样貌。",sex="野兽",age=23,looks=10,showequip={},withCorpse=0},rwnpc06={id="rwnpc06",dsc="此人身着黑衣，头戴黑纱斗笠，但其气息内敛，应当是个高手。",sex="野兽",age=30,looks=20,showequip={},withCorpse=0},rwnpc07={id="rwnpc07",dsc="此人身着蓑衣，头戴斗笠看不清面容，手抱长刀，看起来是个高手。",sex="野兽",age=30,looks=20,showequip={},withCorpse=0},rwnpc11={id="rwnpc11",dsc="他清爽利落，一身文人打扮，手持一支徽笔，指点天下，隐隐有睥睨之姿。",sex="男",age=30,looks=27,showequip={},withCorpse=0},rwnpc12={id="rwnpc12",dsc="她是负责接引游客的接引人。时而安静，低头处理自己的事物，时而活泼，与游客们打成一片。",sex="女",age=26,looks=22,showequip={},withCorpse=0},rwnpc13={id="rwnpc13",dsc="他手如鸡爪，面若鼠狼，身似骷髅。他双腿已断，似乎是从悬崖上摔落到谷底，只能以谷底的蛇虫鼠蚁为食。",sex="男",age=60,looks=12,showequip={},withCorpse=0},rwnpc14={id="rwnpc14",dsc="他手臂绘有淡淡的刺青，一头长发用木簪盘起，虽然身为男子，长相却比寻常女子还要秀气。",sex="男",age=20,looks=24,showequip={},withCorpse=0},rwnpc15={id="rwnpc15",dsc="他左手一支笔，右手一支笔。左手细笔急促，将面具仔细轻描；右手长笔飒挥，将山水描摹于纸上。",sex="男",age=20,looks=19,showequip={},withCorpse=0},rwnpc16={id="rwnpc16",dsc="他容貌如画，漂亮得根本就不似真人这种容貌，这种风仪，根本就已经超越了一切人类的美丽。这种超越的男女，超越了世俗的美态，竟是已不能用言词来形容。",sex="男",age=23,looks=28,showequip={},withCorpse=0},rwnpc17={id="rwnpc17",dsc="只见他白衣洁净，如琼枝一树，栽种在青山绿水之间，尽得天地之精华；又似昆仑美玉，落于东南一隅，散发着淡淡华彩，不由得让人一呆。",sex="男",age=34,looks=30,showequip={},withCorpse=0},rwnpc18={id="rwnpc18",dsc="盛唐阁二阁主，平日虽不坐镇这阁内，但其威严依然让属下噤若寒蝉。",sex="男",age=30,looks=29,showequip={},withCorpse=0},rwnpc20={id="rwnpc20",dsc="他宽衣宽袍，戴着一个木质面具，看不出男女，也看不清他什么模样。",sex="野兽",age=23,looks=10,showequip={},withCorpse=0},rwnpc21={id="rwnpc21",dsc="她身着带兜帽的白色长袍，身边常伴一猫一狗，身形很是敏捷。",sex="女",age=18,looks=22,showequip={},withCorpse=0},rwnpc22={id="rwnpc22",dsc="他是卖面具的商贩，戴着一个颇为滑稽的向日葵面具。",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc23={id="rwnpc23",dsc="他是饭馆大厨，手里拿着擀面杖和公鸡碗，看起来像是在害怕什么。",sex="男",age=30,looks=22,showequip={},withCorpse=0},rwnpc24={id="rwnpc24",dsc="他是卖鞋的商贩，手里正拿着一双精致的靴子，逢人便推销。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc25={id="rwnpc25",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc26={id="rwnpc26",sex="男",age=20,looks=18,showequip={},withCorpse=0},rwnpc27={id="rwnpc27",sex="女",age=20,looks=17,showequip={},withCorpse=0},rwnpc28={id="rwnpc28",dsc="他身着一袭深蓝色布衫，手中书卷已有些陈旧。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc29={id="rwnpc29",dsc="他是一位稍显沧桑的中年道人，面上沉着冷静，不苟言笑。",sex="男",age=35,looks=19,showequip={},withCorpse=0},rwnpc30={id="rwnpc30",dsc="他是一位未通世故的青年道人，脸上挂着孩儿般的微笑。",sex="男",age=20,looks=20,showequip={},withCorpse=0},rwnpc31={id="rwnpc31",dsc="此人头戴斗笠看不清面容，但其气息内敛，应当是个高手。",sex="野兽",age=30,looks=17,showequip={},withCorpse=0},rwnpc32={id="rwnpc32",dsc="此人身着蓑衣，头戴斗笠看不清面容，手抱长刀，看起来是个高手。",sex="野兽",age=30,looks=17,showequip={},withCorpse=0},rwnpc33={id="rwnpc33",dsc="一个须发皆白的老者，精神矍铄，满面红光。",sex="男",age=64,looks=23,showequip={},withCorpse=0},rwnpc34={id="rwnpc34",dsc="她一身水蓝长裙，手里拿着书卷，气质文雅端庄。",sex="女",age=20,looks=20,showequip={},withCorpse=0},rwnpc35={id="rwnpc35",dsc="她一身黄布裙，亦步亦趋的跟着水蓝长裙的女子。",sex="女",age=17,looks=18,showequip={},withCorpse=0},rwnpc36={id="rwnpc36",dsc="他是附近有名的郎中，背着一个药箱，坐在路边的树下。",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc37={id="rwnpc37",dsc="应是受邀而来的侠士，却陷入争执之中。",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc38={id="rwnpc38",dsc="山庄的守卫，身着短打白袍，干净利落。",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc39={id="rwnpc39",dsc="他着一身深灰色的长袍，神情有些倨傲，眼睛在周围人身上扫来扫去。",sex="男",age=30,looks=13,showequip={},withCorpse=0},rwnpc40={id="rwnpc40",dsc="应是来山庄游玩之人。",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc41={id="rwnpc41",dsc="他是一名强盗，却穿金带银，就连手上的宝刀都嵌满宝晶玉石，华贵得不可思议。",sex="男",age=30,looks=25,showequip={},withCorpse=0},rwnpc0701={id="rwnpc0701",dsc="他一身素衣，白须白发，不带尘俗之气，宛如得道高人。",sex="男",age=60,looks=21,showequip={},withCorpse=0},rwnpc0702={id="rwnpc0702",dsc="她满头白发，看起来却极为年轻，气质宛如空谷幽兰，超凡脱尘。",sex="女",age=30,looks=23,showequip={},withCorpse=0},rwnpc0703={id="rwnpc0703",dsc="它立如人高，通体白毛，双目炯炯，有一道刀疤横贯面中，神情严肃。",sex="野兽",age=30,looks=21,showequip={},withCorpse=0},rwnpc0704={id="rwnpc0704",dsc="她身姿纤弱，如风中垂柳，眸中似有水波荡漾，令人望而生怜。",sex="女",age=20,looks=24,showequip={},withCorpse=0},rwnpc0705={id="rwnpc0705",dsc="他虽锦衣玉带，却掩不住一身腌臜气息，实难令人生出敬意。",sex="男",age=34,looks=14,showequip={},withCorpse=0},rwnpc0706={id="rwnpc0706",dsc="她应该是个女子，身材看起来丰腴柔美，却是横眉竖眼，颇为威严。",sex="女",age=20,looks=10,showequip={},withCorpse=0},rwnpc0707={id="rwnpc0707",dsc="这只黑狗浑身肌肉虬结，油亮的皮毛在阳光下泛着幽蓝的光泽，那副凶神恶煞的模样，实不敢让人轻易靠近。",sex="野兽",age=34,looks=14,showequip={},withCorpse=0},rwnpc0708={id="rwnpc0708",dsc="这只白狗端坐着便如人高了，透着一股说不出的灵秀之气，雪白的毛发长而柔顺，修长的身影恍若一位女子。",sex="野兽",age=20,looks=24,showequip={},withCorpse=0},rwnpc0709={id="rwnpc0709",dsc="他身披一袭黑袍，身影如松立寒岩，气势凛冽，绝非寻常之辈。",sex="男",age=60,looks=30,showequip={},withCorpse=0},rwnpc0101={id="rwnpc0101",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc0102={id="rwnpc0102",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc0103={id="rwnpc0103",sex="男",age=30,looks=17,showequip={},withCorpse=0},rwnpc0104={id="rwnpc0104",dsc="他外披素白外袍，内里着黑衣，表面看起来温和谦逊，眼里透出一丝精明与警觉。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc0105={id="rwnpc0105",sex="男",age=20,looks=17,showequip={},withCorpse=0},rwnpc0106={id="rwnpc0106",sex="男",age=35,looks=17,showequip={},withCorpse=0},rwnpc0107={id="rwnpc0107",dsc="他穿着一件粗布衣服，一双手宽厚结实，掌心上布满老茧。",sex="男",age=60,looks=17,showequip={},withCorpse=0},rwnpc0108={id="rwnpc0108",dsc="他身躯若隐若现，头戴斗笠，手执长剑，身如劲松挺立，意态潇洒，气概豪迈。",sex="野兽",age=30,looks=17,showequip={},withCorpse=0},rwnpc0109={id="rwnpc0109",dsc="这是一尊侠客的雕像，头戴斗笠，面庞不清，或为江湖中诸般游侠的写照。",sex="野兽",age=30,looks=17,showequip={},withCorpse=0},rwnpc2601={id="rwnpc2601",dsc="一只灵猴，年岁已高，毛色斑驳但毛发尚还坚挺，目光锐利，似乎知晓诸多江湖秘闻。",sex="野兽",age=60,looks=20,showequip={},withCorpse=0},rwnpc2603={id="rwnpc2603",dsc="苍白无脸的人形，浑身散发阴冷邪气，嗓音怪诞难辨。",sex="野兽",age=30,looks=5,showequip={},withCorpse=1},rwnpc2604={id="rwnpc2604",dsc="她虽然练的是唐门和落月的武学，却自称是大燕复国的希望。其实是一个十足的小鬼头，被安排到红松阁天天练功做苦力。",sex="女",age=10,looks=21,showequip={},withCorpse=0},rwnpc26001={id="rwnpc26001",dsc="黑衣人，手持武器立于林中，白布束腿，行色匆匆，同时神情恍惚，煞气外露。",sex="野兽",age=30,looks=7,showequip={},withCorpse=0},rwnpc26002={id="rwnpc26002",dsc="头戴乌纱冠，肩着金属甲，斗笠黑纱掩去全貌，仅留一双凶戾眼眸，其人早已入狂，全然罔顾生死。",sex="野兽",age=30,looks=7,showequip={},withCorpse=0},rwnpc26003={id="rwnpc26003",dsc="他宽衣宽袍，戴着一个玉制金丝面具，看不出男女，也看不清他什么模样。",sex="野兽",age=25,looks=13,showequip={},withCorpse=0},rwnpc26004={id="rwnpc26004",dsc="此人身形清瘦挺拔，身姿宛若劲竹，体态利落如螳螂。静立时身形笔直，恍若两柄长筷立身天地间。他惯用一柄细剑，与人倒也相配。",sex="男",age=26,looks=10,showequip={},withCorpse=0},rwnpc26005={id="rwnpc26005",dsc="此人体态丰硕，腰间束金甲玉带，肌肤莹白，两缕八字长须随风轻扬。一双手白皙圆润，宛如水润萝卜，他使琴为器，远远看竟也恍惚生出文人之感。",sex="男",age=27,looks=9,showequip={},withCorpse=0},rwnpc26006={id="rwnpc26006",dsc="这是大蛇，花纹黑白相间，它蠢蠢欲动，不知什么品种。",sex="野兽",age=34,looks=14,showequip={},withCorpse=0},rwnpc26007={id="rwnpc26007",dsc="这是小蛇，花纹黑白相间，它蠢蠢欲动，不知什么品种。",sex="野兽",age=34,looks=14,showequip={},withCorpse=0},rwnpc26008={id="rwnpc26008",dsc="它张牙舞爪！",sex="野兽",age=34,looks=14,showequip={},withCorpse=0},rwnpc26009={id="rwnpc26009",dsc="书架中窜出的灵猴土偶，充满了攻击性。",sex="野兽",age=3,looks=5,showequip={},withCorpse=0},rwnpc26010={id="rwnpc26010",dsc="书架后爬出的大蜘蛛，已摆出了攻击的架势。",sex="野兽",age=3,looks=5,showequip={},withCorpse=0}}0000